// ---------------------------------------------------------------------------
// Guard: never redirect away from a page that exists.
//
// Every rule above folds a URL that was NEVER BUILT onto the nearest real page.
// That is correct while the page is missing and wrong the moment it is created,
// because the redirect then shadows the new page — it is served instead of it,
// so the page cannot be read, indexed or ranked.
//
// Measured on 7 October 2026: three Week 52 pages were live-404-free but
// unreachable, each returning 308 to a city hub —
//
//   /places-to-visit-near-jodhpur    -> /jodhpur      (2,475 words, built)
//   /places-to-visit-near-jaisalmer  -> /jaisalmer    (2,342 words, built)
//   /wedding/jaisalmer               -> /jaisalmer    (1,826 words, built)
//
// — because the pages were written weeks after the redirects were generated and
// nobody went back to remove the three rules.
//
// Filtering against the build manifest makes that impossible to repeat: a rule
// disappears automatically as soon as its source becomes a real route, so the
// generated list never has to be hand-pruned again. The manifest is written by
// scripts/gen-route-manifest.mjs in the postbuild step, so it is present
// whenever next.config reads this module.
import { createRequire } from 'node:module';

let knownRoutes = new Set();
try {
  const require_ = createRequire(import.meta.url);
  knownRoutes = new Set(require_('../../generated/known-routes.json'));
} catch {
  // First build in a clean checkout has no manifest yet. Falling back to the
  // unfiltered list keeps the redirects working; the next build filters them.
  knownRoutes = new Set();
}

export const brokenLinkRedirects = rawBrokenLinkRedirects.filter(
  (r) => !knownRoutes.has(r.source),
);

export const shadowedRedirectsRemoved = rawBrokenLinkRedirects
  .filter((r) => knownRoutes.has(r.source))
  .map((r) => r.source);
